// DO NOT EDIT: This file was auto generated by egautotest.

func TestBuildContainer(t *testing.T) {
	ctx, done := testx.Context(t)
	defer done()

	require.Error(t, egdebuild.Prepare(egdebuild.Runner(), nil)(ctx, egtest.Op()), ffierrors.ErrNotImplemented)
	s := testx.ReadMD5(os.TempDir(), "Containerfile")
	require.Equal(t, testx.ReadMD5(filepath.Join(".debian", "Containerfile")), s)
}

func TestDependsBuild(t *testing.T) {
	t.Run("sets build dependencies on new config", func(t *testing.T) {
		cfg := egdebuild.New("testpkg", "ubuntu", "/src", egdebuild.Option.DependsBuild("gcc", "make", "cmake"))
		require.Equal(t, []string{"gcc", "make", "cmake"}, cfg.Dependency.Build)
	})

	t.Run("sets a single build dependency", func(t *testing.T) {
		cfg := egdebuild.New("testpkg", "ubuntu", "/src", egdebuild.Option.DependsBuild("gcc"))
		require.Equal(t, []string{"gcc"}, cfg.Dependency.Build)
	})

	t.Run("replaces existing build dependencies", func(t *testing.T) {
		base := egdebuild.Config{Dependency: egdebuild.Dependency{Build: []string{"old-dep"}}}
		cfg := egdebuild.From(base, egdebuild.Option.DependsBuild("new1", "new2"))
		require.Equal(t, []string{"new1", "new2"}, cfg.Dependency.Build)
	})

	t.Run("clears build dependencies when called with no arguments", func(t *testing.T) {
		base := egdebuild.Config{Dependency: egdebuild.Dependency{Build: []string{"old-dep"}}}
		cfg := egdebuild.From(base, egdebuild.Option.DependsBuild())
		require.Empty(t, cfg.Dependency.Build)
	})

	t.Run("does not affect runtime dependencies", func(t *testing.T) {
		base := egdebuild.Config{Dependency: egdebuild.Dependency{Runtime: []string{"libc6"}}}
		cfg := egdebuild.From(base, egdebuild.Option.DependsBuild("gcc"))
		require.Equal(t, []string{"gcc"}, cfg.Dependency.Build)
		require.Equal(t, []string{"libc6"}, cfg.Dependency.Runtime)
	})

	t.Run("does not affect recommends", func(t *testing.T) {
		base := egdebuild.Config{Dependency: egdebuild.Dependency{Recommends: []string{"reco-dep"}}}
		cfg := egdebuild.From(base, egdebuild.Option.DependsBuild("gcc"))
		require.Equal(t, []string{"gcc"}, cfg.Dependency.Build)
		require.Equal(t, []string{"reco-dep"}, cfg.Dependency.Recommends)
	})

	t.Run("does not affect suggests", func(t *testing.T) {
		base := egdebuild.Config{Dependency: egdebuild.Dependency{Suggests: []string{"sugg-dep"}}}
		cfg := egdebuild.From(base, egdebuild.Option.DependsBuild("gcc"))
		require.Equal(t, []string{"gcc"}, cfg.Dependency.Build)
		require.Equal(t, []string{"sugg-dep"}, cfg.Dependency.Suggests)
	})

	t.Run("preserves other config fields", func(t *testing.T) {
		base := egdebuild.Config{
			Name:         "mypkg",
			Version:      "1.0.0",
			Architecture: "amd64",
		}
		cfg := egdebuild.From(base, egdebuild.Option.DependsBuild("dep1"))
		require.Equal(t, "mypkg", cfg.Name)
		require.Equal(t, "1.0.0", cfg.Version)
		require.Equal(t, "amd64", cfg.Architecture)
		require.Equal(t, []string{"dep1"}, cfg.Dependency.Build)
	})
}
